      let tmp = rocq_array::get::<u64>(&src, j);
      let tmp_1 = rocq_array::get::<u64>(&cash, tmp);
      let tmp_2 = rocq_array::get::<u64>(&src, i);
      std::mem::drop(src);
      let tmp_3 = rocq_array::get::<u64>(&cash, tmp_2);
      std::mem::drop(cash);
      leb(tmp_1, tmp_3)
    } else {
      std::mem::drop(cash);
      std::mem::drop(src);
      true
    }
  } else {
    std::mem::drop(cash);
    std::mem::drop(src);
    false
  }
}

