            let tmp_4 = rocq_array::set::<u64>(v55, v57, tmp_3);
            let tmp_5 = rocq_array::get::<u64>(&cash, i);
            greedy_loop(cash, dl, perm, n, L, tmp_2, tmp_4, add(tot, tmp_5), ())
          }
